setTimeout(() => console.log('5 timer 0 ms'), 0);
setTimeout(() => console.log('7 timer 20 ms'), 20);
Promise.resolve().then(() => console.log('3 promise'));
queueMicrotask(() => console.log('4 microtask'));
setTimeout(() => {
  console.log('6 timer 5 ms');
  Promise.resolve().then(() => console.log('6b promise di dalam timer'));
}, 5);
console.log('2 sinkron');

